<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Maze Discovery</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: system-ui, -apple-system, sans-serif;
    background: #0f1220;
    color: #e8eaf0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 16px;
  }
  h1 { font-size: 1.25rem; font-weight: 600; margin-bottom: 12px; letter-spacing: 0.02em; }
  #ui {
    display: flex;
    gap: 20px;
    align-items: center;
    margin-bottom: 12px;
    flex-wrap: wrap;
    justify-content: center;
  }
  .stat {
    background: #1a1f35;
    border: 1px solid #2a3355;
